# FlipStax - the VS card inventory (Oct 22): how many unique cards, by category and by era. Needs the QA harness:
#   screenshots/qa/tools/venv/bin/python tools/vs-inventory.py
# The cards carry no era field, so the era is tagged here, by hand, on the PEOPLE and TITLES the card is about
# (never on concepts like Pizza v Burgers): C = classic (their peak before about 1995), M = modern (about 1995-2012), N = now
# (2013 and later). A card is 'cross-era' when its two sides are in different eras (a current star v a legend), 'timeless' when
# neither side has an era (foods, habits, ideas), otherwise the era of its sides. Names not listed count as timeless - add them.
import os, sys, json, collections
sys.path.insert(0, os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'screenshots/qa/tools'))
from wkh import View, ensure_server
ERA = {}
def tag(era, names):
    for n in names.split('|'): ERA[n.strip().lower().replace('’', "'")] = era
