tag('N', "Caitlin Clark|Angel Reese|Victor Wembanyama|Luka Dončić|Cooper Flagg|Jayson Tatum|Giannis Antetokounmpo|Joel Embiid|Stephen Curry|Steph Curry|Patrick Mahomes|Josh Allen|Aaron Judge|Shohei Ohtani|Mike Trout|Ronald Acuña Jr.|Connor McDavid|Kylian Mbappé|Erling Haaland|Naomi Osaka|Islam Makhachev|Charles Oliveira|Israel Adesanya|Alex Pereira|Valentina Shevchenko|Sabrina Carpenter|Olivia Rodrigo|Billie Eilish|Ariana Grande|Dua Lipa|Doja Cat|Selena Gomez|Chappell Roan|Bad Bunny|J Balvin|The Weeknd|Travis Scott|Playboi Carti|Post Malone|Morgan Wallen|Luke Combs|Zach Bryan|Ice Spice|Latto|SZA|Summer Walker|Imagine Dragons|Taylor Swift v Travis Kelce|Travis Kelce|Zendaya|Florence Pugh|Anya Taylor-Joy|Sydney Sweeney|Timothée Chalamet|Tom Holland|Glen Powell|Austin Butler|Barbie|Oppenheimer|Parasite|Everything Everywhere All at Once|La La Land|Whiplash|Squid Game|Money Heist|Stranger Things|The Boys|Bridgerton|Outlander|Fourth Wing|A Court of Thorns and Roses|Colleen Hoover|Emily Henry|Taylor Jenkins Reid|Mark Normand v Joe List|Joe List|Hasan Minhaj|Trevor Noah|John Mulaney|Nate Bargatze|Shane Gillis|Tom Segura|Theo Von|Ali Wong|Taylor Tomlinson|MrBeast|Kai Cenat|IShowSpeed|Khaby Lame|Charli D'Amelio|Addison Rae|Bella Poarch|Logan Paul|Jake Paul|Among Us|Fall Guys|Animal Crossing|Stardew Valley|Elden Ring|Dark Souls|Valorant|Fortnite|Roblox|Minecraft|PlayStation 5|Xbox Series X|Love Is Blind|Love Island|Selling Sunset|Vanderpump Rules|The Kardashians|90 Day Fiancé|Below Deck|Married at First Sight|The Masked Singer|Call Her Daddy|SmartLess|Crime Junkie|Morbid|MrBallen Podcast|Rotten Mango|Good Hang with Amy Poehler|Pod Save America|The Megyn Kelly Show|The Ben Shapiro Show|Instagram|TikTok|Tesla|Twitch|Zoom|Microsoft Teams|Airbnb|DoorDash|Uber Eats|Venmo|PayPal|Spotify|Apple Music|HBO Max|Netflix|Kevin Hart v|Cheer|Dance Moms|Catfish|Say Yes to the Dress|Queer Eye|Fixer Upper|Naked and Afraid|RuPaul's Drag Race|Shark Tank|Dragons' Den|The Voice|Joe Rogan Experience|The Joe Rogan Experience|WTF with Marc Maron|The Herd with Colin Cowherd|The Daily|Taylor Swift v|Karaoke|Paparazzi Photos|Modern Influencer Fame|The Met Gala|Fantasy Football")
tag('M', "Eevee|Elf|Bills|Ravens|Ash Ketchum|Red|Pikachu|Charizard|Blastoise|Squirtle|Bulbasaur|Mewtwo|Mew|Gengar|Snorlax")
tag('N', "Avengers: Endgame|Avengers: Infinity War|Viola Davis|Rory McIlroy")
def era_of(name):
    return ERA.get(name.strip().lower().replace('’', "'"))
ensure_server(); v = View(390, 844); v.load(debug=True)
pools = v.J("(()=>{ const P = window.__debug.cardPools(), o = {}; for (const k of ['daily','infinity']) o[k] = P[k].map(c=> ({ cat:c.category, a:c.a, b:c.b })); return o; })()")
LABEL = {'C':'classic (before ~1995)', 'M':'modern (~1995-2012)', 'N':'now (2013 on)'}
def bucket(c):
    ea, eb = era_of(c['a']), era_of(c['b'])
    if not ea and not eb: return 'timeless / no era'
    if ea and eb and ea != eb: return 'cross-era (' + '+'.join(sorted({LABEL[ea][:3].strip(), LABEL[eb][:3].strip()})) + ')'
    return LABEL[ea or eb] + (' - one side only' if not (ea and eb) else '')
allc = [(k, c) for k in pools for c in pools[k]]
print('unique VS cards: %d (Daily %d, Infinity %d; no card is in both)' % (len(allc), len(pools['daily']), len(pools['infinity'])))
print('\nBY CATEGORY (total / Daily / Infinity)')
cat = collections.Counter(c['cat'] for _, c in allc)
for k, n in cat.most_common(): print('  %-10s %4d  %4d  %4d' % (k, n, sum(1 for c in pools['daily'] if c['cat'] == k), sum(1 for c in pools['infinity'] if c['cat'] == k)))
print('\nBY ERA (tagged in this script; people and titles only)')
eb = collections.Counter(bucket(c) for _, c in allc)
for k, n in sorted(eb.items(), key=lambda kv: -kv[1]): print('  %-40s %4d' % (k, n))
simple = collections.Counter()
for _, c in allc:
    b = bucket(c)
    simple['timeless' if b.startswith('timeless') else 'cross-era' if b.startswith('cross') else b.split(' ')[0]] += 1
print('  --', dict(simple))
